// Plainpen store, everything stays in this browser, encrypted at rest.
//
//  * AES-GCM, 256-bit key, generated by WebCrypto and stored NON-EXTRACTABLE in
//    IndexedDB (page script can use the key but can never read its bytes).
//  * Fresh random 96-bit IV for every write.
//  * Portable backups are encrypted with a key derived from your passphrase
//    (PBKDF2-SHA256, 600k iterations, random salt), AES-GCM-256 again.
//  * If IndexedDB or WebCrypto is unavailable (private windows, http://), the app keeps
//    working in memory and tells the user, instead of failing.
import { sanitizeProfile, emptyProfile } from './profile.js';

const DB = 'plainpen', ST = 'kv', ITER = 600000;
const MAX_DRAFT = 6e6;
let mem = new Map();
let status = { persistent: false, encrypted: false, reason: '' };
let keyP = null;

const hasCrypto = () => typeof crypto !== 'undefined' && crypto.subtle && typeof indexedDB !== 'undefined';

function idb() {
  return new Promise((res, rej) => {
    const t = setTimeout(() => rej(new Error('IndexedDB timeout')), 4000);
    const r = indexedDB.open(DB, 1);
    r.onupgradeneeded = () => r.result.createObjectStore(ST);
    r.onsuccess = () => { clearTimeout(t); res(r.result); };
    r.onerror = () => { clearTimeout(t); rej(r.error || new Error('IndexedDB error')); };
    r.onblocked = () => { clearTimeout(t); rej(new Error('IndexedDB blocked')); };
  });
}
async function kvGet(k) {
  const db = await idb();
  try {
    return await new Promise((res, rej) => { const q = db.transaction(ST).objectStore(ST).get(k); q.onsuccess = () => res(q.result); q.onerror = () => rej(q.error); });
  } finally { db.close(); }
}
async function kvSet(k, v) {
  const db = await idb();
  try {
    await new Promise((res, rej) => { const tx = db.transaction(ST, 'readwrite'); tx.objectStore(ST).put(v, k); tx.oncomplete = res; tx.onerror = () => rej(tx.error); tx.onabort = () => rej(tx.error || new Error('aborted')); });
  } finally { db.close(); }
}
async function kvClear() {
  const db = await idb();
  try { await new Promise((res, rej) => { const tx = db.transaction(ST, 'readwrite'); tx.objectStore(ST).clear(); tx.oncomplete = res; tx.onerror = () => rej(tx.error); }); } finally { db.close(); }
}

async function getKey() {
  if (!keyP) keyP = (async () => {
    let k = await kvGet('key');
    if (!(k && k.type === 'secret')) {
      k = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
      await kvSet('key', k);
    }
    return k;
  })();
  return keyP;
}

const enc = new TextEncoder(), dec = new TextDecoder();
async function seal(obj) {
  const key = await getKey();
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(JSON.stringify(obj)));
  return { v: 1, iv, ct };
}
async function open(rec) {
  if (!rec || !(rec.iv instanceof Uint8Array) || rec.iv.length !== 12 || !(rec.ct instanceof ArrayBuffer)) throw new Error('corrupt record');
  const key = await getKey();
  return JSON.parse(dec.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv: rec.iv }, key, rec.ct)));
}

export async function init() {
  if (!hasCrypto()) { status = { persistent: false, encrypted: false, reason: 'Secure storage needs https:// or localhost. Working in memory only.' }; return status; }
  try { await getKey(); status = { persistent: true, encrypted: true, reason: '' }; }
  catch (e) { keyP = null; status = { persistent: false, encrypted: false, reason: 'Browser storage is blocked (private window?). Your changes will not persist.' }; }
  return status;
}
export const getStatus = () => status;

async function put(name, obj) {
  if (!status.persistent) { mem.set(name, obj); return false; }
  try { await kvSet(name, await seal(obj)); return true; }
  catch (e) { mem.set(name, obj); status = { ...status, reason: e && e.name === 'QuotaExceededError' ? 'Browser storage is full.' : 'Could not save to browser storage.' }; return false; }
}
async function take(name) {
  if (!status.persistent) return mem.get(name) ?? null;
  try { const rec = await kvGet(name); return rec ? await open(rec) : null; }
  catch { return null; }   // unreadable or tampered record => start clean rather than crash
}

export async function loadProfile() { return sanitizeProfile(await take('profile')); }
export const saveProfile = (p) => put('profile', p);
export async function loadDraft() { const d = await take('draft'); return typeof d === 'string' ? d : ''; }
export async function saveDraft(text) { return text.length > MAX_DRAFT ? false : put('draft', text); }

export async function wipeAll() {
  mem = new Map();
  try { if (hasCrypto()) await kvClear(); } catch {}
  keyP = null;
  return init();
}

/* --------------------------------------------------------------- backups */
const b64 = (u8) => { let s = ''; for (let i = 0; i < u8.length; i += 0x8000) s += String.fromCharCode.apply(null, u8.subarray(i, i + 0x8000)); return btoa(s); };
const unb64 = (s) => { if (typeof s !== 'string' || s.length > 40e6 || !/^[A-Za-z0-9+/]*={0,2}$/.test(s)) throw new Error('Bad backup file.'); return Uint8Array.from(atob(s), (c) => c.charCodeAt(0)); };

async function derive(pass, salt, iter) {
  const base = await crypto.subtle.importKey('raw', enc.encode(pass), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey({ name: 'PBKDF2', hash: 'SHA-256', salt, iterations: iter }, base, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
}

export async function exportBackup(profile, pass) {
  if (!pass || pass.length < 8) throw new Error('Use a passphrase of at least 8 characters.');
  const salt = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12));
  const key = await derive(pass, salt, ITER);
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(JSON.stringify(profile))));
  return JSON.stringify({ format: 'plainpen-backup', v: 1, kdf: 'PBKDF2-SHA256', iter: ITER, cipher: 'AES-GCM-256', salt: b64(salt), iv: b64(iv), ct: b64(ct) });
}

export async function importBackup(jsonText, pass) {
  if (typeof jsonText !== 'string' || jsonText.length > 40e6) throw new Error('Backup file is too large.');
  let f; try { f = JSON.parse(jsonText); } catch { throw new Error('Not a Plainpen backup.'); }
  if (!f || f.format !== 'plainpen-backup' || f.v !== 1 || f.cipher !== 'AES-GCM-256') throw new Error('Not a Plainpen backup.');
  if (!Number.isInteger(f.iter) || f.iter < 100000 || f.iter > 2000000) throw new Error('Unsupported backup settings.');
  const salt = unb64(f.salt), iv = unb64(f.iv), ct = unb64(f.ct);
  if (salt.length !== 16 || iv.length !== 12) throw new Error('Bad backup file.');
  try {
    const key = await derive(pass, salt, f.iter);
    return sanitizeProfile(JSON.parse(dec.decode(await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ct))));
  } catch { throw new Error('Wrong passphrase, or the file was modified.'); }
}

export { emptyProfile };
